__BLONDIN_PAYLOAD__
EXPECTED_SHA=f32e3aec503e6185fb54455d5fb61e7d0af0707be4f640c69f54f53407ebe7e5
ACTUAL_SHA="$(sha256sum "$TMP" | awk '{print $1}')"
[[ "$EXPECTED_SHA" == "$ACTUAL_SHA" ]] || { echo '[ERREUR] Integrite invalide.'; exit 1; }
bash -n "$TMP" || { echo '[ERREUR] Syntaxe invalide.'; exit 1; }
if [[ -f "$TARGET" ]]; then
  cp -p -- "$TARGET" "$BACKUP/gestionnaire-batocera.$(date +%Y%m%d-%H%M%S).bak"
fi
if [[ -f "$LAUNCHER" ]]; then
  cp -p -- "$LAUNCHER" "$BACKUP/lanceur-ports.$(date +%Y%m%d-%H%M%S).bak"
fi
install -m 755 "$TMP" "$TARGET"
cat > "$LAUNCHER" <<'__BLONDIN_LAUNCHER__'
#!/bin/bash
export DISPLAY="${DISPLAY:-:0}"
export BLONDIN_PORTS_PAD=1
SCRIPT=/userdata/system/gestionnaire-batocera.sh
if [[ ! -f "$SCRIPT" ]]; then
  echo '[ERREUR] Gestionnaire introuvable.'
  sleep 5
  exit 1
fi
# Fenetre centre approximativement sur DP-1 3440x1440 ;
# labwc peut ajuster le placement des fenetres XWayland.
exec xterm -bg black -fg white -fa 'DejaVu Sans Mono' -fs 32 \
  -geometry '100x29+650+85' -sb -rightbar -sl 5000 \
  -title 'Gestionnaire Batocera - BLONDIN EDITION' \
  -e /bin/bash "$SCRIPT"
__BLONDIN_LAUNCHER__
chmod 755 "$LAUNCHER"
echo '[OK] Gestionnaire v3.0.15 TEST installe.'
echo '[OK] Diagnostic pagine : Haut/Bas, Gauche/Droite.'
echo '[OK] Lanceur Ports en fenetre noire, position centrale demandee.'
echo '[OK] Configuration manette .keys conservee.'
echo "[INFO] Sauvegardes : $BACKUP"

echo '[INFO] Gestion > Gestionnaire dans Ports > Installer / réparer : illustrations GitHub.'
